"""
    Lookup collection and suffix based on the name of the collection as used by GEE

    Parameters
    ==========
    collection_name: str, GEE name of the collection, eg. 'COPERNICUS/S2'

    Returns
    =======
    collection: str, user-friendly name of the collection, e.g. 'Sentinel2'
    suffix:  str, contraction of collection name, used in the filenames of plots
    """
def get_collection_and_suffix(collection_name: Any) -> object {
    if (collection_name == 'COPERNICUS/S2') {
        collection = 'Sentinel2';
        satellite_suffix = 'S2';
    } elif (collection_name == 'LANDSAT8') {
        collection = 'Landsat8';
        satellite_suffix = 'L8';
    } elif (collection_name == 'LANDSAT7') {
        collection = 'Landsat7';
        satellite_suffix = 'L7';
    } elif (collection_name == 'LANDSAT5') {
        collection = 'Landsat5';
        satellite_suffix = 'L5';
    } elif (collection_name == 'LANDSAT4') {
        collection = 'Landsat4';
        satellite_suffix = 'L4';
    } else {
        raise RuntimeError("Unknown collection_name {}".format(collection_name));
    }
    return (collection, satellite_suffix);
}

""" Very simple prior estimator only for MH as it checks if the parametrisation is inside of respective domain or not.
        This simulates uniform distribution.
    Args:
        theta: (tuple): parameter point
        parameter_intervals (list of pairs): parameter domains, (min, max)

    Returns:
        1 for all parametrisations inside the parameter space
        0 otherwise

    @author: xhajnal
    """
def prior(theta: Any, parameter_intervals: Any) -> object {
    for (index, value) in enumerate(theta) {
        if (
            (theta[index] < parameter_intervals[index][0])
            or (theta[index] > parameter_intervals[index][1])
        ) {
            return 0;
        }
    }
    return 1;
}

"""
    Implements the intersection over union (IoU) between box1 and box2

    Arguments:
    box1 -- first box, list object with coordinates (box1_x1, box1_y1, box1_x2, box_1_y2)
    box2 -- second box, list object with coordinates (box2_x1, box2_y1, box2_x2, box2_y2)
    """
def iou(box1: Any, box2: Any) -> object {
    (box1_x1, box1_y1, box1_x2, box1_y2) = box1;
    (box2_x1, box2_y1, box2_x2, box2_y2) = box2;
    xi1 = max(box1_x1, box2_x1);
    yi1 = max(box1_y1, box2_y1);
    xi2 = min(box1_x2, box2_x2);
    yi2 = min(box1_y2, box2_y2);
    inter_width = xi2 - xi1;
    inter_height = yi2 - yi1;
    inter_area = max(inter_width, 0) * max(inter_height, 0);
    box1_area = abs(((box1_x2 - box1_x1) * (box1_y2 - box1_y1)));
    box2_area = abs(((box2_x2 - box2_x1) * (box2_y2 - box2_y1)));
    union_area = (box1_area + box2_area) - inter_area;
    iou = inter_area / union_area;
    return iou;
}

"""
    Returns an object's name (str) given its 'objID' (int) and a reference 'objList' (list)
    Format of 'objList' is [['name_1', id_1], ['name_2', id_2], ...]
    """
def getObjName(objID: Any, objList: Any) -> object {
    for i in range(0, len(objList)) {
        if (objList[i][1] == objID) {
            return objList[i][0];
        }
    }
}

